import { useLocation } from 'react-router-dom';
import { PaymentGuide } from '~/entities/payment/ui/payment-guide';
import { closeWebview } from '~/shared/api/web-view';

export const PaymentGuidePage = () => {
  const { search } = useLocation();
  const searchParams = new URLSearchParams(search);
  const defaultTabIndex = Number(searchParams.get('defaultTabIndex'));
  return <PaymentGuide onClose={closeWebview} defaultTabIndex={defaultTabIndex} />;
};
