import { Tab, TabGroup, TabList, TabPanel, TabPanels } from '@headlessui/react';
import clsx from 'clsx';
import { Fragment } from 'react/jsx-runtime';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { overlay } from '~/shared/lib/overlay';
import { GuideQRScan } from './guide-qr-scan';
import { GuideQRView } from './guide-qr-view';

export type PaymentGuideProps = {
  defaultTabIndex?: number;
  onClose?: () => void;
};
export const PaymentGuide = ({ defaultTabIndex = 1, onClose }: PaymentGuideProps) => {
  const { navigateBack } = useNavigate();
  const close = () => {
    overlay.closeAll();
    onClose?.();
    navigateBack();
  };

  return (
    <div className="wrap bgw">
      <div className="sub-top">
        <h2>{i18n.t('usageGuide')}</h2>
        <button type="button" onClick={close} className="btn close-btn">
          <span>{i18n.t('close')}</span>
        </button>
      </div>
      <div className="content sub min-h-screen">
        <TabGroup defaultIndex={defaultTabIndex}>
          <TabList className="board-list-tab">
            <Tab as={Fragment}>
              {({ selected }) => (
                <button type="button" className={clsx(selected && 'on', 'tab-btn')}>
                  {i18n.t('qrNfcScan')}
                </button>
              )}
            </Tab>
            <Tab as={Fragment}>
              {({ selected }) => (
                <button type="button" className={clsx(selected && 'on', 'tab-btn')}>
                  {i18n.t('showQR')}
                </button>
              )}
            </Tab>
          </TabList>
          <TabPanels>
            <TabPanel>
              <GuideQRScan />
            </TabPanel>
            <TabPanel>
              <GuideQRView />
            </TabPanel>
          </TabPanels>
        </TabGroup>
      </div>
    </div>
  );
};
